function toggleOverview(){if(!renderer||activeDialog)return;renderer.overview=!renderer.overview;$('#overview').textContent=renderer.overview?'◎':'▦';$('#overview').setAttribute('aria-label',renderer.overview?'回到跟随视角':'切换全图视角');toast(renderer.overview?'全图视角 · 仍可以移动，按 M 返回':'跟随视角');}
function paintMinimap(){const canvas=$('#minimap');if(!canvas)return;const ctx=canvas.getContext('2d'),l=game.level,n=l.size,unit=canvas.width/n;ctx.fillStyle='#84cd32';ctx.fillRect(0,0,canvas.width,canvas.height);for(let z=0;z<n;z++)for(let x=0;x<n;x++)if(l.grid[z][x]){ctx.fillStyle='#b4e45d';ctx.fillRect(x*unit,(n-1-z)*unit,unit+.3,unit+.3);}const pos=(x,z)=>[(x/l.cellSize+(n-1)/2+.5)*unit,(n-.5-(z/l.cellSize+(n-1)/2))*unit];for(const b of l.beans){if(game.collected.has(b.id))continue;const[x,y]=pos(b.x,b.z);const effect=beanEffect(b),danger=effect!=='add',high=b.value>1||danger;ctx.fillStyle=effect==='zero'?'#b91f40':effect==='subtract'?'#3d2052':b.value===1000?'#b78009':b.value===500?'#e9439f':b.value===100?'#e9683e':b.value===10?'#c44ab8':b.value===5?'#258dce':'#dfaa1f';ctx.beginPath();ctx.arc(x,y,Math.max(1.6,unit*(high?.23:.14)),0,Math.PI*2);ctx.fill();if(high){ctx.fillStyle='white';ctx.font=`bold ${Math.max(6,unit*(b.value>=100?.36:.39))}px sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(effect==='zero'?'×0':effect==='subtract'?`−${Math.abs(b.value)}`:b.value,x,y);}}for(const h of l.hazards){const[x,y]=pos(h.x,h.z);ctx.fillStyle='#ed7697';ctx.fillRect(x-2.5,y-2.5,5,5);}for(const s of game.shieldPickups){const[x,y]=pos(s.x,s.z),r=Math.max(3,unit*.3);ctx.fillStyle=s.available?'#2db8e4':'#869fb2';ctx.strokeStyle='white';ctx.lineWidth=1.2;ctx.beginPath();ctx.moveTo(x,y-r);ctx.lineTo(x+r,y);ctx.lineTo(x,y+r);ctx.lineTo(x-r,y);ctx.closePath();ctx.fill();ctx.stroke();}for(const m of game.monsters){if(m.defeated)continue;const[x,y]=pos(m.x,m.z);ctx.fillStyle=['chase','windup','dash'].includes(m.state)?'#e24d65':m.color||ENEMY_RANKS[m.rank||'normal'].color;ctx.strokeStyle=m.rank==='boss'?'#ffd54d':'white';ctx.lineWidth=1.2;ctx.beginPath();ctx.moveTo(x,y-unit*.28);ctx.lineTo(x+unit*.25,y+unit*.2);ctx.lineTo(x-unit*.25,y+unit*.2);ctx.closePath();ctx.fill();ctx.stroke();}for(const p of l.portals){const[x,y]=pos(p.x,p.z);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(x,y,unit*.39,0,Math.PI*2);ctx.fill();ctx.fillStyle='white';ctx.font=`bold ${Math.max(8,unit*.55)}px sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(p.label,x,y);}const [x,y]=pos(game.player.x,game.player.z);ctx.fillStyle='#443976';ctx.strokeStyle='white';ctx.lineWidth=2.5;ctx.beginPath();ctx.arc(x,y,unit*.34,0,Math.PI*2);ctx.fill();ctx.stroke();}
function perform(action){if(activeDialog)return;if(game.status==='ready')startGame();if(game.action(action)){if(action!=='attack')beep(action);}else if(action==='roll')toast(game.player.ground===null?'落地后才能翻滚':'翻滚还在冷却中');else if(action==='dive')toast('等落地或冷却结束后再飞扑');else if(action==='attack'&&game.respawnDelay)toast('正在回安全区，复活后可继续攻击');}
function resetPlayer(){if(activeDialog)return;if(game.status==='ready')startGame();if(game.action('reset')){attackInput.clear();keys.clear();resetStick();toast('已复位到检查点 · 10 秒后可再次复位');}else if(game.resetCooldown>0)toast(`复位还需 ${Math.ceil(game.resetCooldown)} 秒`);}
function input(){return{x:(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0)+stick.x,z:(keys.has('KeyW')||keys.has('ArrowUp')?1:0)-(keys.has('KeyS')||keys.has('ArrowDown')?1:0)+stick.z};}
function handleEvent(e){if(adventure.handleEvent(e))return;beep(e.type==='bean'&&e.effect!=='add'?e.effect:e.type);const p=game.player;if(e.type==='bean'){const effect=e.effect||'add',color=effect==='zero'?'#f2556d':effect==='subtract'?'#a875cc':e.value===1000?'#ffe784':e.value===500?'#ff72b4':e.value===100?'#ff8758':e.value===10?'#d459ca':e.value===5?'#44aaf0':'#ffd057';renderer.burst(p.x,p.y+1,p.z,color,effect==='zero'?24:effect==='subtract'?14:e.value>1?14:5);$('#score-pop').textContent=effect==='zero'?'×0 · 积分清零':`${e.delta<0?'−':'+'}${Math.abs(e.delta)} 分`;$('#score-pop').dataset.value=e.value;$('#score-pop').dataset.effect=effect;$('#score-pop').classList.add('show');scoreFeedbackUntil=performance.now()+(effect==='add'?1000:1800);if(effect==='zero')toast('碰到 ×0 豆，积分清零！正分豆已重新出现');else if(effect==='subtract')toast(`吃到扣分豆：扣 ${Math.abs(e.value)} 分，当前 ${e.score} 分`);}if(e.type==='shieldCollected'){renderer.burst(e.x,p.y+1,e.z,'#8cddff',18);toast('护盾已装备 · 挡一次敌人攻击，拾取点 100 秒后刷新');}if(e.type==='shieldUsed'){renderer.burst(e.x,p.y+1,e.z,'#b4eaff',24);toast('护盾挡住了攻击，已消耗！');}if(e.type==='shieldReady')toast('护盾已刷新，返回蓝色底座可再次拾取');if(e.type==='enemyWarning')toast(`${e.enemyName||ENEMY_RANKS[e.rank].name}正在蓄力：侧移躲开，或用锤打断！`);if(e.type==='weapon')toast(`已装备${WEAPONS[e.weapon].name}`);if(e.type==='monsterHit')renderer.burst(e.x,.9,e.z,'#ffb2cb',7);if(e.type==='monsterDefeated')toast(`${e.enemyName||ENEMY_RANKS[e.rank].name}已击败，继续吃豆探索！`);if(e.type==='damage')toast(`${e.damage===2?'被首领重击':'被怪物碰到了'} · 剩余 ${e.health} 颗心`);if(e.type==='knockout')toast('生命耗尽，回安全区补满 · 积分保留');if(e.type==='projectilePop')renderer.burst(e.x,e.y,e.z,'#8cddff',4);if(e.type==='checkpoint')toast('安全区已记录，掉落从这里继续');if(e.type==='portal'){renderer.burst(p.x,p.y+1,p.z,'#ac83f0',20);toast(`${e.label} 门传送成功 · 离开出口后可以再次使用`);}if(e.type==='gate')toast('等绿灯再过门，也可以找一条绕路');if(e.type==='fall')toast('回安全区继续，已获得的积分都保留');if(e.type==='hit')toast('小心机关，跳跃或绕路试试');if(e.type==='win'){renderer.burst(p.x,p.y+2,p.z,'#ffd368',65);victory(e.reward);}}
function frame(now){const dt=Math.min((now-last)/1000||.016,.1);last=now;accumulator+=dt;while(accumulator>=1/120){if(game.status==='playing'&&!game.respawnDelay)attackInput.tick(1/120);else attackInput.clear();game.step(1/120,input());accumulator-=1/120;}while(game.events.length)handleEvent(game.events.shift());renderer.draw(game,Math.min(dt,.05),now/1000);updateCombatUI();adventure.frame(dt);$('#timer').textContent=formatTime(game.elapsed);$('#score-total').textContent=`${game.score} / ${game.level.requiredScore} 分`;$('#score-current').textContent=game.score;$('.bean-goal').classList.toggle('large-goal',Math.max(game.score,game.level.requiredScore)>=1000);$('#bean-count').textContent=game.beanPickups;const nextBean=game.beanRespawns.size?Math.max(0,Math.ceil(Math.min(...game.beanRespawns.values())-game.time)):0;$('#bean-refresh').textContent=game.beanRespawns.size?`下颗 ${nextBean} 秒刷新 · ${game.beanRespawns.size} 颗待刷新`:'正分豆吃掉后 30 秒刷新';const pct=Math.max(0,Math.min(100,Math.round(game.score/game.level.requiredScore*100)));if(now>scoreFeedbackUntil)$('#score-pop').classList.remove('show');$('#progress-fill').style.width=`${pct}%`;$('#progress-text').textContent=`${pct}%`;if(now-lastMapPaint>120){paintMinimap();lastMapPaint=now;}
 for(const [id,cd,max]of [['roll',game.player.rollCd,PHYSICS.rollCooldown],['dive',game.player.diveCd,PHYSICS.diveCooldown]]){const b=$(`#${id}`);b.querySelector('i').style.height=`${cd/max*100}%`;b.querySelector('small').textContent=cd>0?`${cd.toFixed(1)}s`:id==='roll'?'Shift':'E';b.classList.toggle('cooldown',cd>0);b.setAttribute('aria-label',`${id==='roll'?'翻滚':'飞扑'}${cd>0?`，冷却${cd.toFixed(1)}秒`:''}`);}if(now>toastUntil)$('#toast').classList.remove('show');requestAnimationFrame(frame);}
$('#code-entry').onclick=codeDialog;$('#overview').onclick=toggleOverview;$('#minimap-button').onclick=toggleOverview;$('#copy-code').onclick=async()=>{try{await navigator.clipboard.writeText(game.level.code.split(' / ')[0]);toast(`地图码 ${game.level.code} 已复制`);}catch{toast(`当前地图码：${game.level.code}`);}};$('#start').onclick=startGame;$('#start-challenges').onclick=()=>adventure.challengeGuide();$('#help').onclick=help;$('#level-select').onclick=()=>map();$('#pause').onclick=pause;$('#restart').onclick=()=>{if(game.level.mode==='challenge'){attackInput.clear();game.retryChallenge();}else loadLevel(game.level.id,true);};$('#modal-close').onclick=()=>closeDialog();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')&&activeDialog!=='win')closeDialog();});
