function updateCombatUI(){const p=game.player;$('#health').textContent='♥'.repeat(p.health)+'♡'.repeat(p.maxHealth-p.health);$('#health').setAttribute('aria-label',`生命 ${p.health} / ${p.maxHealth}`);$('#health').classList.toggle('low',p.health<=1);$('#monster-count').textContent=`击败 ${game.defeatedMonsters} / ${game.monsters.length}`;const pickup=game.shieldPickups[0],refresh=pickup&&!pickup.available?Math.max(0,Math.ceil(pickup.respawnAt-game.time)):0,shield=$('#shield-status');shield.textContent=`◇ ${p.shield?'护盾 ×1':pickup?.available?'护盾可拾取':'未装备护盾'}${refresh?` · ${refresh}s 刷新`:''}`;shield.classList.toggle('active',!!p.shield);shield.classList.toggle('cooldown',!p.shield&&!!refresh);shield.title=`${p.shield?'可挡一次敌人攻击，使用后消失。':'走近地图上的蓝色盾牌即可拾取。'}${refresh?`拾取点 ${refresh} 秒后刷新。`:'拾取后 100 秒刷新。'}暂停时倒计时停止。`;shield.setAttribute('aria-label',shield.title);if(shownWeapon!==game.weapon){shownWeapon=game.weapon;for(const button of document.querySelectorAll('[data-weapon]')){const on=button.dataset.weapon===game.weapon;button.classList.toggle('equipped',on);button.setAttribute('aria-pressed',String(on));}$('#attack-symbol').textContent=WEAPONS[game.weapon].icon;$('#weapon-name').textContent=WEAPONS[game.weapon].name;}}
