const movement=['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'];
addEventListener('keydown',e=>{
 if(e.target.matches('input,textarea,select,[contenteditable=true]')){if(e.code==='Escape')closeDialog();return;}
 if(e.target.closest('button,a[href]')&&['Space','Enter','NumpadEnter'].includes(e.code))return;
 if(e.key==='Tab'&&activeDialog){const items=[...$('.modal').querySelectorAll('button:not([hidden]),input,select')].filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0]?.focus();}return;}
 if(!activeDialog&&handleAttackKey(e,attackInput))return;
 if(!activeDialog&&resetInput.keyDown(e))return;
 if(['Space',...movement,'ShiftLeft','ShiftRight'].includes(e.code))e.preventDefault();if(e.repeat){if(movement.includes(e.code)&&!activeDialog)keys.add(e.code);return;}
 if(e.code==='Escape'||e.code==='KeyP'){if(activeDialog==='win')return;pause();return;}
 if(e.key==='?'||e.code==='KeyH'){if(activeDialog==='help')closeDialog();else if(activeDialog!=='win')help();return;}
 if(activeDialog)return;
 if(['Digit1','Digit2','Digit3','Numpad1','Numpad2','Numpad3'].includes(e.code)){equip(['hammer','launcher','sword'][Number(e.code.at(-1))-1]);return;}
 if(['KeyZ','KeyX','KeyC','KeyG'].includes(e.code)){adventure.useItem({KeyZ:'jetpack',KeyX:'crate',KeyC:'grapple',KeyG:'fish'}[e.code]);return;}
 if(e.code==='KeyV'){adventure.wardrobe();return;}
 if(e.code==='KeyB'){adventure.challengeGuide();return;}
 if(e.code==='KeyQ'){const choices=Object.keys(WEAPONS);equip(choices[(choices.indexOf(game.weapon)+1)%choices.length]);return;}
 if(e.code==='KeyM'){toggleOverview();return;}
 if(e.code==='Enter'&&game.status==='ready'){startGame();return;}
 if(movement.includes(e.code)){if(game.status==='ready')startGame();keys.add(e.code);}
 if(e.code==='Space')perform('jump');if(e.code==='ShiftLeft'||e.code==='ShiftRight')perform('roll');if(e.code==='KeyE')perform('dive');
});addEventListener('keyup',e=>{handleAttackKey(e,attackInput);resetInput.keyUp(e);keys.delete(e.code);});
let stickPointer=null;const joy=$('#touch-joystick');function resetStick(){stick={x:0,z:0};stickPointer=null;joy.querySelector('span').style.transform='';}
joy.addEventListener('pointerdown',e=>{if(activeDialog)return;e.preventDefault();if(game.status==='ready')startGame();stickPointer=e.pointerId;joy.setPointerCapture(e.pointerId);moveStick(e);});function moveStick(e){if(e.pointerId!==stickPointer)return;const r=joy.getBoundingClientRect();let dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,len=Math.hypot(dx,dy),max=r.width*.31;if(len>max){dx*=max/len;dy*=max/len;}stick={x:dx/max,z:-dy/max};joy.querySelector('span').style.transform=`translate(${dx}px,${dy}px)`;}joy.addEventListener('pointermove',moveStick);joy.addEventListener('pointerup',resetStick);joy.addEventListener('pointercancel',resetStick);joy.addEventListener('lostpointercapture',resetStick);
function leave(){attackInput.clear();resetInput.clear();keys.clear();resetStick();if(game.status==='playing'&&!activeDialog)pause();}addEventListener('blur',leave);document.addEventListener('visibilitychange',()=>{if(document.hidden)leave();});
